theorem AbcAdaptation.Tripod.Northcott.coeff_minpoly_int_mem_Icc {K : Type*} [Field K] [NumberField K] {y : K}
    (hy : IsIntegral ℤ y) {d : ℕ} (hd : Module.finrank ℚ K ≤ d) {B : ℝ}
    (hB : ∀ φ : K →+* ℂ, ‖φ y‖ ≤ B) (i : ℕ) :
    (minpoly ℤ y).coeff i ∈ Set.Icc (-(coeffBoundOf d B : ℤ)) (coeffBoundOf d B) := by sorry

theorem AbcAdaptation.Tripod.Fermat.Proper.CurveDeriv.valuation_aeval_derivative_eq_one (hQ : ∀ q : ℚ, algebraMap ℚ K q ∈ O) {x : K}
    (hx : x ∈ O) {q : ℚ[X]} (hq : q.Separable) (hv : O.valuation (aeval x q) < 1) :
    O.valuation (aeval x (derivative q)) = 1 := by sorry

theorem AbcAdaptation.Tripod.Fermat.Proper.CurveDeriv.exists_irreducible_valuation_lt_one (hQ : ∀ q : ℚ, algebraMap ℚ K q ∈ O) {x : K}
    (hx : x ∈ O) {p : ℚ[X]} (hp : p ≠ 0) (hv : O.valuation (aeval x p) < 1) :
    ∃ q : ℚ[X], Irreducible q ∧ O.valuation (aeval x q) < 1 := by sorry
